 async void CaptureFieldKit(){try{CloseMenu();paused=true;camera.Fov=35;hudRoot.Visible=false;terrainRoot.Visible=worldRoot.Visible=buildRoot.Visible=weaponRoot.Visible=false;if(distantTerrain!=null)distantTerrain.Visible=false;ClearEnemies();game.World.Changes.Time=900;var stage=new Node3D();AddChild(stage);Box(stage,new(0,-.1f,0),new(20,.2f,12),new(.20f,.24f,.20f));for(int i=0;i<10;i++){var n=new Node3D{Position=new((i%5-2)*2,0,(i/5)*2.5f),Scale=Vector3.One*2};stage.AddChild(n);FieldItemArt(n,i);n.AddChild(new Label3D{Text=ExpeditionGame.ThrowableNames[i],Position=new(0,.65f,0),FontSize=18,PixelSize=.005f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}var flame=new Node3D{Position=new(0,1,-2),Scale=Vector3.One*2};stage.AddChild(flame);FlamethrowerArt(flame);camera.GlobalPosition=new(8,7,-11);camera.LookAt(new Vector3(0,.5f,1));await ArtShot("field-kit-01-throwables-flamethrower");ClearChildren(stage);Box(stage,new(0,-.1f,0),new(20,.2f,12),new(.20f,.24f,.20f));for(int f=0;f<4;f++)for(int l=1;l<=(f>=2?3:2);l++){var n=new Node3D{Position=new((f-1.5f)*3,0,(l-1)*2.4f),Scale=Vector3.One*2};stage.AddChild(n);FieldKitItemArt(n,200+f*10+l);n.AddChild(new Label3D{Text=ExpeditionGame.HarvestToolName(f,l),Position=new(0,1,0),FontSize=18,PixelSize=.005f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}camera.GlobalPosition=new(8,8,-10);camera.LookAt(new Vector3(0,.3f,2));await ArtShot("field-kit-02-tiered-tools");stage.QueueFree();GD.Print("PASS / field kit model captures");GetTree().Quit();}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
